--
-- Table structure for table `devicetokens`
--

DROP TABLE IF EXISTS `devicetokens`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `devicetokens` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `userId` int(11) NOT NULL,
  `expoPushToken` varchar(255) NOT NULL,
  `deviceId` varchar(255) DEFAULT NULL,
  `platform` varchar(50) DEFAULT NULL COMMENT 'ios, android, web',
  `deviceModel` varchar(255) DEFAULT NULL,
  `isActive` tinyint(1) NOT NULL DEFAULT 1,
  `lastActive` datetime DEFAULT NULL,
  `createdAt` datetime NOT NULL DEFAULT current_timestamp(),
  `updatedAt` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `device_tokens_user_id` (`userId`),
  KEY `device_tokens_expo_push_token` (`expoPushToken`),
  KEY `device_tokens_is_active` (`isActive`),
  CONSTRAINT `devicetokens_ibfk_1` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

